import { Prism, languages } from '../prismCore'
import './javascript'

var js = languages.js;
var templateString = js['template-string'];

// see the pattern in prism-javascript.js
var templateLiteralPattern = templateString.pattern.source;
var {
	pattern: interpolationPattern,
	inside: { ['interpolation-punctuation']: interpolationPunctuationObject }
} = templateString.inside.interpolation;

/**
 * Creates a new pattern to match a template string with a special tag.
 *
 * This will return `undefined` if there is no grammar with the given language id.
 *
 * @param {string} language The language id of the embedded language. E.g. `markdown`.
 * @param {RegExp} tag The regex pattern to match the tag.
 * @returns {object | undefined}
 * @example
 * createTemplate('css', /\bcss/.source);
 */
var createTemplate = (language, tag) => ({
	pattern: RegExp('((?:' + tag.source + ')\\s*)' + templateLiteralPattern),
	lookbehind: true,
	greedy: true,
	inside: {
		'template-punctuation': {
			pattern: /^`|`$/,
			alias: 'string'
		},
		'embedded-code': {
			pattern: /[\s\S]+/,
			alias: language
		}
	}
});


js['template-string'] = [
	// styled-jsx:
	//   css`a { color: #25F; }`
	// styled-components:
	//   styled.h1`color: red;`
	createTemplate('css', /\b(?:styled(?:\([^)]*\))?(?:\s*\.\s*\w+(?:\([^)]*\))*)*|css(?:\s*\.\s*(?:global|resolve))?|createGlobalStyle|keyframes)/),

	// html`<p></p>`
	// div.innerHTML = `<p></p>`
	createTemplate('html', /\bhtml|\.\s*(?:inner|outer)HTML\s*\+?=/),

	// svg`<path fill="#fff" d="M55.37 ..."/>`
	createTemplate('svg', /\bsvg/),

	// md`# h1`, markdown`## h2`
	createTemplate('markdown', /\b(?:markdown|md)/),

	// gql`...`, graphql`...`, graphql.experimental`...`
	createTemplate('graphql', /\b(?:gql|graphql(?:\s*\.\s*experimental)?)/),

	// sql`...`
	createTemplate('sql', /\bsql/),

	// vanilla template string
	templateString
];

/**
 * Returns a specific placeholder literal for the given language.
 *
 * @param {number} counter
 * @param {string} language
 * @returns {string}
 */
var getPlaceholder = (counter, language) => `___${language.toUpperCase()}_${counter}___`

/**
 * Returns the tokens of `Prism.tokenize` but also runs the `before-tokenize` and `after-tokenize` hooks.
 *
 * @param {string} code
 * @param {any} grammar
 * @param {string} language
 * @returns {(string|Token)[]}
 */
var tokenizeWithHooks = (code, grammar, language) => {
	var env = {
		code: code,
		grammar: grammar,
		language: language
	};
	Prism.hooks.run('before-tokenize', env);
	env.tokens = Prism.tokenize(env.code, env.grammar);
	Prism.hooks.run('after-tokenize', env);
	return env.tokens;
}

/**
 * Returns the token of the given JavaScript interpolation expression.
 *
 * @param {string} expression The code of the expression. E.g. `"${42}"`
 * @returns {Token}
 */
var tokenizeInterpolationExpression = (expression) => {
	var tempGrammar = {
		['interpolation-punctuation']: interpolationPunctuationObject
	};

	/** @type {Array} */
	var tokens = Prism.tokenize(expression, tempGrammar);
	if (tokens.length == 3) {
		/**
		 * The token array will look like this
		 * [
		 *     ["interpolation-punctuation", "${"]
		 *     "..." // JavaScript expression of the interpolation
		 *     ["interpolation-punctuation", "}"]
		 * ]
		 */
		tokens.splice(1, 1, ...tokenizeWithHooks(tokens[1], js, 'javascript'));
	}

	return new Prism.Token('interpolation', tokens, 'language-javascript', expression);
}

/**
 * Tokenizes the given code with support for JavaScript interpolation expressions mixed in.
 *
 * This function has 3 phases:
 *
 * 1. Replace all JavaScript interpolation expression with a placeholder.
 *    The placeholder will have the syntax of a identify of the target language.
 * 2. Tokenize the code with placeholders.
 * 3. Tokenize the interpolation expressions and re-insert them into the tokenize code.
 *    The insertion only works if a placeholder hasn't been "ripped apart" meaning that the placeholder has been
 *    tokenized as two tokens by the grammar of the embedded language.
 *
 * @param {string} code
 * @param {object} grammar
 * @param {string} language
 * @returns {Token}
 */
var tokenizeEmbedded = (code, grammar = {}, language) => {
	// 1. First filter out all interpolations

	// because they might be escaped, we need a lookbehind, so we use Prism
	/** @type {(Token|string)[]} */
	var _tokens = Prism.tokenize(code, {
		'interpolation': {
			pattern: interpolationPattern,
			lookbehind: true
		}
	});

	// replace all interpolations with a placeholder which is not in the code already
	var placeholderCounter = 0;
	/** @type {Object<string, string>} */
	var placeholderMap = {};
	var embeddedCode = _tokens.map(token => {
		if (typeof token == 'string') return token;
		var interpolationExpression = token.content;

		var placeholder;
		while (code.indexOf(placeholder = getPlaceholder(placeholderCounter++, language)) != -1) { /* noop */ }
		placeholderMap[placeholder] = interpolationExpression;
		return placeholder;
	}).join('');

	// 2. Tokenize the embedded code

	var embeddedTokens = tokenizeWithHooks(embeddedCode, grammar, language);

	// 3. Re-insert the interpolation

	var placeholders = Object.keys(placeholderMap);
	var l = placeholders.length;
	var parentCount = 0;
	var parents = [];

	/**
	 *
	 * @param {(Token|string)[]} tokens
	 * @returns {void}
	 */
	var walkTokens = tokens => {
		for (var i = 0; i < tokens.length && placeholderCounter < l; i++) {
			var token = tokens[i];
			var content = token.content;

			if (content) parents[parentCount++] = token;
			if (Array.isArray(content)) {
				walkTokens(content);
			}
			else {
				var placeholder = placeholders[placeholderCounter];
				var s = content || token;

				var index = s.indexOf(placeholder);
				if (index + 1) {
					++placeholderCounter;

					var before = s.slice(0, index);
					var interpolation = placeholderMap[placeholder];
					var length = placeholder.length;
					var middle = tokenizeInterpolationExpression(interpolation);
					var after = s.slice(index + length);

					var replacement = [middle];
					var j = 0;
					if (before) replacement.unshift(before);
					if (after) {
						var afterTokens = [after];
						walkTokens(afterTokens);
						replacement.push(...afterTokens);
					}
					for (; j < parentCount; ) parents[j++].length += interpolation.length - length;

					if (!content) {
						tokens.splice(i, 1, ...replacement);
						i += replacement.length - 1;
					} else {
						token.content = replacement;
					}
				}
			}
			if (content) parentCount--;
		}
	}
	placeholderCounter = 0;
	walkTokens(embeddedTokens);

	return new Prism.Token(language, embeddedTokens, 'language-' + language, code);
}

/**
 * The languages for which JS templating will handle tagged template literals.
 *
 * JS templating isn't active for only JavaScript but also related languages like TypeScript, JSX, and TSX.
 */
var langs = ['javascript', 'typescript', 'jsx', 'tsx', 'js', 'ts']

Prism.hooks.add('after-tokenize', env => {
	if (!langs.includes(env.language)) {
		return;
	}

	var langAlias = 'language-' + env.language;

	/**
	 * Finds and tokenizes all template strings with an embedded languages.
	 *
	 * @param {(Token | string)[]} tokens
	 * @returns {void}
	 */
	var findTemplateStrings = tokens => {
		for (var i = 0, l = tokens.length; i < l; i++) {
			var token = tokens[i];
			var content = token.content;

			if (!Array.isArray(content)) {
				continue;
			}

			if (token.type == 'template-string') {
				/**
				 * A JavaScript template-string token will look like this:
				 *
				 * ["template-string", [
				 *     ["template-punctuation", "`"],
				 *     (
				 *         An array of "string" and "interpolation" tokens. This is the simple string case.
				 *         or
				 *         ["embedded-code", "..."] This is the token containing the embedded code.
				 *                                  It also has an alias which is the language of the embedded code.
				 *     ),
				 *     ["template-punctuation", "`"]
				 * ]]
				 */

				var embedded = content[1];
				if (content.length == 3 && embedded.type == 'embedded-code') {
					// get string content
					var code = embedded.content;
					var language = embedded.alias;

					content[1] = tokenizeEmbedded(code, languages[language], language);
				}
			} else {
				findTemplateStrings(content);
			}
		}
	}

	findTemplateStrings(env.tokens);
});
